INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 4, 'theory', 'Quiz: functions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 4, 0, 'How do you return a value at the end of a function body in idiomatic Rust?', '["write the last expression without a semicolon", "return value; on the last line", "assign the value to a variable result", "call exit(value)"]', 0, 'The last expression without ; becomes the result. return is kept for early exit.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 4, 1, 'What will the compiler say about fn f() -> i32 { 5; }?', '["all fine, it returns 5", "expected i32, found (): the semicolon turned the expression into a statement", "the function returns None", "you need to write return"]', 1, 'A semicolon discards the value; a block with no final expression has type ().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 4, 2, 'What does a function without the arrow -> return?', '["nothing: there is no value at all", "None", "a compile error", "() — the unit, a value of the empty type"]', 3, 'The type () has a single value, which is also (); this is what fn main and println! return.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 4, 3, 'How do you return two numbers from a function at once?', '["write two returns in a row", "pass the two results through global variables", "return a tuple: -> (i32, i32)", "it can''t be done"]', 2, 'A tuple is a compound value of several elements: let (a, b) = f();');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 4, 4, 'Can you set a default value for a parameter in Rust, like Python''s def f(a, b=1)?', '["no, Rust has no such parameters", "yes, with an equals sign in the signature", "yes, but only for numbers", "only in macros"]', 0, 'There are no optional parameters: you write separate functions or use Option and structs instead.');
